    derive: (i, deep) => {
      const p = (deep && deep.params) || {};
      const growth = p.growth || 1, k = p.peak || 3;
      const reqDay = i.dau * 1e6 * i.perUser * growth, req = reqDay / 86400, peakReq = req * k, units = i.outTok + i.inTok * PREFILL_W;
      return { growth, k, reqDay, req, peakReq, inTok: i.inTok, outTok: i.outTok, gpuTok: i.gpuTok, units,
        outPeak: peakReq * i.outTok, inPeak: peakReq * i.inTok, gpus: Math.ceil((peakReq * units) / i.gpuTok / 0.7),
        answerS: i.outTok / USER_TPS, histGB: (reqDay * MSG_KB) / 1e6 };
    },

