        stream: { whole: 'Ответ целиком в конце: секунды пустого экрана.', sse: 'Ответ потоком по SSE.' },
        limit: { rps: 'Лимит в запросах: тяжёлые клиенты забирают GPU.', tokens: 'Лимит в токенах в минуту.' },
        route: { rr: 'Round robin: неровная загрузка, кэш случайно.', least: 'Наименее загруженная: ровно, но без кэша префиксов.', affinity: 'По префиксу с порогом загрузки.' },
        scale: { peak: 'Мощность под пик всегда: простой вне пика.', util: 'Масштаб по загрузке GPU: отказы на всплеске.', queue: 'Масштаб по очереди, тёплый резерв и прогноз.' },
        prio: { fifo: 'Одна очередь без границ: люди ждут за пакетными.', prio: 'Приоритеты и ограниченная очередь.' },
